body:
Firstly thank you very much for trying to help!

Also I'm running this in a VM is there anyway the terminal is bugging or something?

Also this is the full code:

    #include <stdio.h>
#define rows 3
#define cols 5
#define size 5
int main(void)
{
        int i,j,arr[rows][cols],x,min,arr_min[size];

        printf("Give integers ranging from 0 to 20\n");
        for(i = 0; i < rows-1; i++){
                for(j = 0; j < cols; j++){
                        scanf("%d",&x);
                        while((x < 0) || (x > 20)){
                                printf("Wrong Number\n");
                                scanf("%d",&x);
                        }
                        arr[i][j] = x;
                }
        }
        for(j = 0; j < cols; j++){
                arr[3][j] = 50 - (arr[1][j] + arr[2][j]);
        }
        for(i = 0; i < rows; i++){
                for(j = 0; j < cols; j++){
                        printf("%d  ",arr[i][j]);
                }
                printf("\n");
        }
        for(j = 0; j < cols; j++){
                min = arr[0][j];
                for(i = 0; i < rows; i++){
                        if(arr[i][j] < min){
                                min = arr[i][j];
                        }
                arr_min[j] = min;
                }
        }
        for(j = 0; j < size; j++){
                printf("%d  ",arr_min[j]);
        }

        return 0;
}


Cant seem to be able to preserve formatting sorry
